<script setup lang="ts">
import { Route, Wallet, Receipt, TrendingUp, Clock3, Plus, ArrowRight } from 'lucide-vue-next'
import type { Trip, Expense } from '~/types/models'
const db = useDb(), trips = ref<Trip[]>([]), expenses = ref<Expense[]>([]), error = ref(''), busy = ref(true)
onMounted(async () => { try { [trips.value, expenses.value] = await Promise.all([db.trips(), db.expenses()]) } catch(e) { error.value = message(e) } finally { busy.value = false } })
const month = ref(localDate().slice(0, 7))
const filtered = computed(() => trips.value.filter(t => localDate(t.start_at).slice(0, 7) === month.value && t.status !== 'cancelado'))
const matchingExpenses = computed(() => expenses.value.filter(e => filtered.value.some(t => t.id === e.trip_id)))
const income = computed(() => serviceIncome(filtered.value))
const spending = computed(() => expensesTotal(matchingExpenses.value))
const profit = computed(() => routeProfit(income.value, matchingExpenses.value))
const outstanding = computed(() => pendingCollection(filtered.value, matchingExpenses.value))
const categoryTotals = computed(() => { const map = new Map<string,number>(); matchingExpenses.value.forEach(e => { const key = e.expense_type?.name || 'Otros'; map.set(key,(map.get(key)||0)+Number(e.amount)) }); return [...map.entries()].sort((a,b) => b[1]-a[1]).slice(0,6) })
const statuses: Record<string,string> = { planificado:'Planificado', en_curso:'En curso', finalizado:'Finalizado', cancelado:'Cancelado' }
</script>
<template><div class="page-heading"><div><h1>Hola, bienvenido 👋</h1><p class="muted">Aquí tienes el resumen de tu actividad.</p></div><label class="month-label">Mes <input v-model="month" type="month" /></label></div>
<div v-if="error" class="alert danger">{{error}}</div><div v-if="busy" class="empty">Cargando resumen...</div><template v-else><div class="stats-grid five"><div class="card stat"><span class="stat-icon blue"><Route :size="21"/></span><span class="muted">Viajes del mes</span><strong>{{filtered.length}}</strong></div><div class="card stat"><span class="stat-icon green-icon"><Wallet :size="21"/></span><span class="muted">Servicios acordados del mes</span><strong>{{euro(income)}}</strong></div><div class="card stat"><span class="stat-icon red"><Receipt :size="21"/></span><span class="muted">Gastos totales</span><strong>{{euro(spending)}}</strong></div><div class="card stat"><span class="stat-icon green-icon"><TrendingUp :size="21"/></span><span class="muted">Beneficio operativo</span><strong class="green">{{euro(profit)}}</strong></div><div class="card stat"><span class="stat-icon orange"><Clock3 :size="21"/></span><span class="muted">Pendiente de cobrar del mes</span><strong>{{euro(outstanding)}}</strong></div></div>
<div class="dashboard-grid"><section class="card panel"><h2>Gastos por categoría</h2><div v-if="!categoryTotals.length" class="empty compact">Sin gastos este mes.</div><div v-for="([name,value],i) in categoryTotals" :key="name" class="bar-line"><div><span class="dot" :style="{background:['#2873ee','#1abca6','#f4b64f','#9277ef','#ee697b','#9da9be'][i]}"/> {{name}}</div><b>{{euro(value)}}</b><div class="bar-track"><div class="bar-fill" :style="{ width: `${spending ? value / spending * 100 : 0}%`, background:['#2873ee','#1abca6','#f4b64f','#9277ef','#ee697b','#9da9be'][i] }"></div></div></div></section><section class="card panel"><div class="panel-header"><h2>Viajes recientes</h2><NuxtLink to="/trips" class="text-link">Ver todos <ArrowRight :size="15"/></NuxtLink></div><div v-if="!filtered.length" class="empty compact">Aún no tienes viajes este mes.</div><NuxtLink v-for="t in filtered.slice(0,5)" :key="t.id" :to="`/trips/${t.id}`" class="recent-row"><span class="recent-icon"><Route :size="18"/></span><span class="recent-label"><b>{{t.origin}} → {{t.destination}}</b><small>{{t.platform?.name || 'Sin plataforma'}} · {{shortDate(t.start_at)}}</small></span><span class="recent-right"><strong>{{euro(t.service_price)}}</strong><small>{{statuses[t.status]}}</small></span></NuxtLink></section></div>
<div class="page-heading lower-heading"><div><h2>Todos tus viajes</h2></div><NuxtLink to="/trips/new" class="button primary"><Plus :size="17"/> Nuevo viaje</NuxtLink></div><div class="card table-wrap"><table><thead><tr><th>Trayecto</th><th>Plataforma</th><th>Fecha</th><th>Precio</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="t in filtered.slice(0,6)" :key="t.id"><td><b>{{t.origin}} → {{t.destination}}</b></td><td>{{t.platform?.name || '—'}}</td><td>{{shortDate(t.start_at)}}</td><td>{{euro(t.service_price)}}</td><td><span class="pill" :class="t.status">{{statuses[t.status]}}</span></td><td><NuxtLink class="text-link" :to="`/trips/${t.id}`">Ver →</NuxtLink></td></tr><tr v-if="!filtered.length"><td colspan="6" class="empty">Sin viajes registrados en este mes.</td></tr></tbody></table></div>
<p class="footer-note">Resumen por mes de inicio del viaje, incluidos los planificados y en curso; excluye cancelados. El pendiente corresponde a esos viajes. Beneficio operativo = precio del servicio − gastos propios no reembolsables. No incluye impuestos ni costes generales.</p></template>
</template>
